// The Objections screen's own static master-sheet content (distinct from
// lib/salesScript/objData.ts's OBJ — that one feeds the per-section
// slide-in panel; this is the standalone "Objections Master Sheet" tab
// screen with its own category tabs). Ported verbatim — do not edit.

export type ObjScreenTab = { key: string; label: string };
export type ObjScreenPage = { id: string; html: string };

export const OBJECTIONS_SCREEN_DIAL_HTML: string = "<h2>Objections Master Sheet</h2><p>All rebuttals word for word from your scripts. Tap a category to switch. Use alongside any script.</p>\n<div class=\"agent-note\" style=\"margin-top:12px;\"><strong>Key Terms -- Building Pain / Why:</strong>\n<ul style=\"margin:10px 0 4px 18px;padding:0;\">\n<li>\"Now correct me if I'm wrong (Name), but looking at the situation here....\"</li>\n<li>\"Would that be a fair assumption?\"</li>\n<li>\"Now would that help y'all out?\"</li>\n</ul></div>";

export const OBJECTIONS_SCREEN_TABS: ObjScreenTab[] = [
  { key: "fe_intro", label: "FEX Intro" },
  { key: "fe_numbers", label: "FEX Numbers" },
  { key: "fe_ssn", label: "FEX SSN / Banking" },
  { key: "mp_key", label: "MP Key Objections" },
  { key: "mp_all", label: "MP All Objections" },
  { key: "iul_all", label: "IUL Objections" },
  { key: "fia_all", label: "Fixed Indexed Annuity" },
];

export const OBJECTIONS_SCREEN_PAGES: ObjScreenPage[] = [
  { id: "fe_intro", html: "<div class=\"obj-item\"><div class=\"oq\">1. \"Where are you calling from?\" / \"Are you the VA?\"</div><div class=\"oa\">I manage the brokerage that handles all the veteran's final expense options.<div class=\"opb\"><em>Push Back \"Who is that?\":</em> I'm an underwriter that helps go over your life options and eligibility.</div></div></div>\n<div class=\"obj-item\"><div class=\"oq\">2. \"I already have funeral coverage in place!\"</div><div class=\"oa\">Perfect, glad you have that taken care of. So you were planning on leaving some extra money behind for the loved ones, correct?<div class=\"opb\"><em>Push Back \"I already have that covered as well\":</em> Got it, so a lot of veterans are looking to utilize their veterans discount. Did you get that through us or a Private Carrier? Let me update that on our file.... How much are you currently covered for? Perfect, how long ago did you get that in place?<br/><br/><em>IF 5 years or MORE:</em> Perfect, I'm glad you got that when you were a little bit younger. Were you planning on using that for a burial or cremation? [Spend their coverage: Overstate funeral costs + inflation, Mortgage/Debts/Credit Cards, Left Over Bills]<br/><br/><em>IF 5 years or LESS:</em> Let me make sure your veterans discount was applied.... What do you pay on that each month? [See if you can beat quote]<br/>IF You CAN Beat Price: CONTINUE WITH SCRIPT.. DON'T JUMP TO NUMBERS<br/>IF You CAN'T Beat Price: Were you planning on using that for a burial or cremation? [Spend their coverage -- High funeral costs, left over bills, inflation]</div></div></div>\n<div class=\"obj-item\"><div class=\"oq\">3. \"Looking for benefits, disability, etc!\"</div><div class=\"oa\">Absolutely, I can point you in the right direction with that once we get done. Do you currently have anything in place to help cover your funeral god forbid you passed away today? Then go back to the script.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">4. \"You are the 10th person that has called me!\"</div><div class=\"oa\">I completely understand, but it doesn't look like anyone has contacted you for the Veterans Program.... Do you currently have anything in place to help cover your funeral god forbid you passed away today? Then go back to the script.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">5. \"I'm not interested!\"</div><div class=\"oa\">Did you know what this was about??? This is to cover your funeral expenses. Do you currently have anything in place to help cover your funeral god forbid you passed away today? Then go back to the script.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">6. \"I don't remember filling this out!\"</div><div class=\"oa\">No worries, it does take us about a few weeks to get to your file. You put your date of birth as ___ correct? Now, most people's main concern is to make sure that their final expense doesn't fall a burden on their loved ones or leave some extra money behind. Do you currently have anything in place? Then go back to the script.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">7. \"This is not a good time / I'm busy!\"</div><div class=\"oa\">I understand (client first name), however this is the only time slot we have available for you. But don't worry -- this will only take a few minutes. Then go back to the script.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">8. \"When I pass away the VA will take care of my burial.\"</div><div class=\"oa\">Of course, if you are planning on being buried in a national cemetery, the plot and headstone is covered. However that still leaves behind $8,000 to $10,000 that the family has to cover. Did you have anything to cover the rest of those expenses? Then go back to the script.</div></div>" },
  { id: "fe_numbers", html: "<div class=\"obj-item\"><div class=\"oq\">1. \"I need to think about it -- make sure it's affordable!\"</div><div class=\"oa\">Of course.... It is something that you need to go over.... Did you want to think about which option you should go with.... OR if you felt like you needed this at all?<div class=\"opb\"><em>Which Option:</em> Do you mind if I make a recommendation for you.... Most veterans in your position start with bare minimum, make sure you can get the coverage and foot in the door and make sure [insert their need] is covered for [beneficiary's name]. And if later on you decide you want to go with the silver or gold option then we can always increase it for you. But the main thing today is to make sure you can get the coverage, and make sure [beneficiary's name] is covered. Does that make sense? [proceed to application]<br/><br/><em>Don't Need:</em> Spin back on why. Did they have any insurance? Or any money saved up? If yes, is it enough? 10k isn't enough for burial -- most add 5k to factor in inflation. HARD CLOSE: Shove the why down their throat till they pick an option or hang up.</div></div></div>\n<div class=\"obj-item\"><div class=\"oq\">2. \"I need to talk to my wife about it!\"</div><div class=\"oa\">I completely understand.... I'm the same way I talk to my wife about everything.... She is the beneficiary of the plan, and she has to know what's going on. You can't keep this a secret that's for sure.... Do you need to talk to her about which one to go with.... or if you need this at all?<div class=\"opb\"><em>Which Option:</em> Do you mind if I make a recommendation for you.... Most veterans in your position start with bare minimum. And later when you talk to the wife if you two decide to go with the silver or gold option then we can always increase it. But the main thing today is to make sure you can get the coverage. Does that make sense??? [proceed to application]<br/><br/><em>If approved you'll get everything in the mail in the next 7-10 days and you have a physical copy to show her. But as of right now there's not really much for you to talk to her about. Does that make sense???</em><br/><br/><em>Push Back 2:</em> [client name], we can both agree that accidents can occur at any time, correct? Now if something happened to you while driving on the way home tomorrow.... and you had put this protection in place for your wife. Do you think that you would have regretted getting [beneficiary's name] covered??? On the worst day of [beneficiary's name] life would you rather have her receive a check or have to write a check???</div></div></div>\n<div class=\"obj-item\"><div class=\"oq\">3. \"I'm just shopping around today!\"</div><div class=\"oa\">I completely understand, I'm the same exact way, I want to make sure I'm not paying more than I need to for anything. Now the good news is.... with the veterans program they do the shopping for you with all 26 partnered carriers in the country to get you the lowest rate. But of course our goal today is to make sure you can get the coverage. Which one option makes the most sense to you.... BRONZE.... SILVER...., OR GOLD? [proceed to application]</div></div>\n<div class=\"obj-item\"><div class=\"oq\">4. \"Can you send it in the mail?\"</div><div class=\"oa\">Absolutely, you'll get everything in the mail in about a week. But coverage only activates once we set it up, so the sooner we do it, the sooner your family is protected. Which one option makes the most sense to you.... BRONZE.... SILVER...., OR GOLD? [proceed to application]</div></div>" },
  { id: "fe_ssn", html: "<div class=\"obj-item\"><div class=\"oq\">Social Security Objections</div><div class=\"oa\">\n<em>Push Back 1:</em> It's just for the application....<br/><br/>\n<em>Push Back 2:</em> I completely understand. That's just how they go over your medical history, and make sure you don't weigh 500 pounds or are like tied to a hospital bed.... Does that make sense??? Now go ahead with the social.<br/><br/>\n<em>Push Back 3:</em> Most importantly that's the ONLY thing on your death certificate when you die for them to pay out your loved ones. Does that make sense??? Now go ahead with your social.<br/><br/>\n<em>Push Back 4:</em> The carrier just has to verify the SSN on file so god forbid when the time comes your loved ones receive a check instead of giving out a check. Does that make sense??? Now go ahead with your social.<br/><br/>\n<em>Last Resort:</em> Send a pic of the application with carrier name and their name. \"Do you see your name there??? And the name of the carrier on the screen? Got it so you were able to validate everything there right??? Perfect, now go ahead with the social.\"<br/><br/>\n<em>IF THEY HAVE AN IPHONE:</em> Send text above. Ask to hop on FaceTime to process the rest of the application for full transparency. Then ask for social.\n</div></div>\n<div class=\"obj-item\"><div class=\"oq\">Banking Objections</div><div class=\"oa\">\n<em>\"Why do you need my bank account number?\"</em><br/>Yeah.... it's just to make your payment. Does that make sense? Now go ahead with the account number.<br/><br/>\n<em>Push Back 1:</em> I completely understand -- now quick question [Client's Name]: have you ever given or received a check from anyone in your lifetime? At the bottom of every check you'll see the same routing and account number because that information can't be used to buy something online. All this is doing is putting an electronic check on file. Does that make sense? Now go ahead with the account number.<br/><br/>\n<em>Push Back 2:</em> I completely understand -- so the state is required by law to validate that the insured and payor of the policy is the same person before anything is submitted. Just for your safety and the safety of others. Does that make sense? Now go ahead with the account number.<br/><br/>\n<em>Last resort / For full transparency:</em> Do you receive text messages to this phone? I'm gonna send you a picture of my screen. [Send a pic of the application with carrier name and their name] Do you see your name there? And the name of the carrier on the screen? Got it -- so you were able to validate everything there right? Perfect, now go ahead with the account number.<br/><br/>\n<em>IF iPhone:</em> Ask to hop on FaceTime to process the rest of the application for full transparency. Then ask for account number.\n</div></div>" },
  { id: "mp_key", html: "<div class=\"agent-note\"><strong>Personalized Intro -- Used When Client Is Not Informed on the Coverage:</strong> \"Well, you know how when the primary income earner unexpectedly passes away or gets disabled, and their loved ones are left without the income to keep up with the mortgage, they ultimately end up losing the home and all the equity they have saved up in it? Well what we do is we help people qualify for financial protection plans, so they don't have to worry about what might happen and the bank doesn't take the...\" <em>(back into script w/ question)</em></div>\n<div class=\"obj-section-label\">WHO DO YOU WORK FOR / WHO ARE YOU WITH</div>\n<div class=\"obj-item\"><div class=\"oq\">\"Where are you calling from?\"</div><div class=\"oa\"><em>*Disarm*</em> I'm just the state's licensed medical underwriter that's been assigned to your file. <em>(back to script)</em></div></div>\n<div class=\"obj-section-label\">I DON'T REMEMBER / I NEVER SUBMITTED THAT</div>\n<div class=\"obj-item\"><div class=\"oq\">\"I don't remember doing that.\"</div><div class=\"oa\"><em>*Disarm*</em> Oh yeah, I apologize -- we do hear that a lot, people forget since it's been a month or two. How familiar are you with what this even is? <em>*Say Personalized Intro*</em></div></div>\n<div class=\"obj-section-label\">I'M NOT INTERESTED</div>\n<div class=\"obj-item\"><div class=\"oq\">\"I'm not interested.\"</div><div class=\"oa\">I kinda figured you weren't interested or already got some coverage in place, I'm just calling to update the system. You're not still getting a bunch of calls about this are you? <em>(playful)</em>.... Let me get this updated on our end so you don't get any more calls. Was it just too expensive, you didn't qualify? What ended up happening?</div></div>\n<div class=\"obj-section-label\">I ALREADY GOT IT TAKEN CARE OF / I ALREADY HAVE</div>\n<div class=\"obj-item\"><div class=\"oq\">\"I already have insurance.\"</div><div class=\"oa\">I figured that's why they have us calling to update the system. You're not still getting a bunch of calls about this are you? <em>*optional playfully acknowledge*</em> Let me get this updated real quick -- what was the name of the agent that initially set you up? Gotcha, yeah he's one of the junior underwriters at the firm. Did you get the policy while you were _(age)_, or was it before or afterwards? Ok and which carrier did _(agent name)_ set you up with? Right, and it was for the full mortgage of _(mortgage amount)_? <em>*Use quoter to pinpoint premium*</em> Ok and the premium was about _(premium)_, right? <em>*Seed doubt into replacement*</em> Go ahead and grab a pen and paper for me real quick, we'll get this fixed for you... <em>*Replace*</em></div></div>\n<div class=\"obj-section-label\">I DON'T NEED THIS / WE'LL BE FINE</div>\n<div class=\"obj-item\"><div class=\"oq\">\"We don't need mortgage protection.\"</div><div class=\"oa\">Yeah, I'm not exactly sure what your situation looks like financially, everyone's different. But correct me if I'm wrong, you intentionally sent in this request to make sure your home's taken care of for your family when you pass, would that be a fair assumption? <em>(back to intro)</em></div></div>\n<div class=\"obj-section-label\">I'M BUSY / CALL ME BACK LATER</div>\n<div class=\"obj-item\"><div class=\"oq\">\"I'm busy.\"</div><div class=\"oa\">Well just to see if it even makes sense for me to call you back later, were you maybe looking for anything specific or just wanting to check out all the different options? <em>*If they say it a second time, go to appointment setting script*</em></div></div>\n<div class=\"obj-section-label\">I'M NOT READY FOR ANYTHING RIGHT NOW</div>\n<div class=\"obj-item\"><div class=\"oq\">\"I'm not buying anything today.\" (Think about it)</div><div class=\"oa\">Yeah that's not a problem, I'm not sure if this coverage would make sense for you in the first place, or what you'd even qualify for. We'd really have to know more about what your situation looks like, and what that gap of coverage might look like.... so just to see if there is a way I can help... <em>(into next question or underwriting)</em></div></div>\n<div class=\"obj-section-label\">SOCIAL SECURITY NUMBER</div>\n<div class=\"obj-item\"><div class=\"oq\">\"Why do you need my Social Security number?\" / \"I'm not comfortable giving that out.\"</div><div class=\"oa\">Understood, I hear ya (client's name). The insurance carrier requires that because that's how they're going to check your medical and prescription history, and it also prevents fraud so someone's not signing up for coverage in your name. Does that make sense? Okay cool -- confirm that social with me again?<div class=\"opb\"><em>If they give more pushback:</em> We actually have insurance that if anybody were able to get through all of our firewalls and access your info, it would cover you for up to a million dollars. That should be enough, right? <em>(wait for response)</em> Ok, go ahead with the social.</div></div></div>\n<div class=\"obj-section-label\">BANKING</div>\n<div class=\"obj-item\"><div class=\"oq\">\"Why do you need my bank information?\" / \"I don't want to give that out.\"</div><div class=\"oa\">The insurance carrier either requires a voided check or account number to verify there is no insurance fraud, money laundering, or anything else fraudulent linked to your account -- and of course that's also how you'll be paying for the policy once you're approved. Anyway, looks like the address we have on file to mail the policy out to is ___?<div class=\"opb\"><em>If they're still giving pushback:</em> I also just texted you a link to the Department of Insurance to look up my information and make sure I'm legit. Let me know when you get the link. <em>(walk them through how to verify your license: https://sbs.naic.org/solar-external-lookup)</em></div></div></div>" },
  { id: "mp_all", html: "<div class=\"obj-item\"><div class=\"oq\">1. \"I'm not interested.\"</div><div class=\"oa\">Understandably, most people aren't interested until they get cancer, disabled, or God forbid pass away -- anyway it looks like the address we have on file for the home is ____?<div class=\"opb\"><em>2nd time:</em> Hmm, well I'm assuming what was on your mind when you submitted this request to our office was simply providing some sort of practical, affordable coverage to protect the home and your family God forbid when something does happen to you…?<br/><br/><em>3rd time:</em> Ok, well are you afraid the price is going to be too high or are you afraid you're going to be declined?<br/><br/><em>Declined:</em> Correct, I see that on your file here. I'm the senior medical underwriter that's been assigned to figure out some options you will qualify for.<br/><br/><em>Price too high:</em> Correct, I see that on your file here -- looks like you were quoted some pretty high numbers by one of my sales reps. I'm the manager that handles the ___(county/city)___ area that's been assigned to figure out some more practical, affordable options that make sense for your budget.</div></div></div>\n<div class=\"obj-item\"><div class=\"oq\">2. \"Take me off the list.\"</div><div class=\"oa\">To be frank with you ___, there is no list -- I'm sorry you may be confused, this is the request YOU submitted in regards to protecting your family God forbid you were to get cancer, disabled, or pass away. Anyway, it looks like the address we have on file for the home is ____?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">3. \"Is this required?\"</div><div class=\"oa\">Oooof… I mean… technically they won't take your home away if you don't... uh but I will tell you… you'd be one of the rare people not to put it in place since it's just such crucial coverage… It'd be like driving a car without car insurance, if that makes sense. <em>*(act confused and a bit thrown off guard as to why they would even ask that)*</em></div></div>\n<div class=\"obj-item\"><div class=\"oq\">4. \"If they hang up.\"</div><div class=\"oa\">Hi ___, seems we got disconnected there. <em>(go back into script or repeat what they said before they hung up)</em></div></div>\n<div class=\"obj-item\"><div class=\"oq\">5. \"I can't afford it right now.\"</div><div class=\"oa\">I completely understand -- I see on your file here you were quoted some pretty steep numbers by our sales rep, which is the reason for my call. I'm the medical underwriter that has been assigned to figure out something more practical and affordable. Anyway, the address we have on file for the home is ____?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">6. \"Now's not the right time.\"</div><div class=\"oa\">Totally get it. These programs are based on age and health -- so waiting can actually increase the cost or limit your eligibility later. If we lock in a small amount of coverage now while you're in good health, that would be important to you, correct?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">7. \"I don't own that house anymore.\" / \"We're going to sell the home.\"</div><div class=\"oa\">Perfect -- this coverage actually sticks with you and transfers with you when you buy a new home. Do you plan on staying local or are you moving out of state?<div class=\"opb\"><em>Already sold:</em> Perfect -- did you purchase a new home or are you renting?<br/><br/><em>Bought new home:</em> Perfect, it looks like that's why your file was flagged here and coming up as incomplete… what's the new updated mortgage address? I'll update your file for you.<br/><br/><em>Now renting:</em> Perfect, it looks like that's why your file was flagged here and coming up as incomplete… We also handle life insurance and protection that covers you if God forbid you were to become sick, disabled, or pass away. Have you guys gotten that set up yet?</div></div></div>\n<div class=\"obj-item\"><div class=\"oq\">8. \"I don't really understand how it works.\"</div><div class=\"oa\">Totally fair. Let me simplify it: mortgage protection is just a policy that's set up to pay off your home or help your family cover payments if something happens to you. You know how when the primary income earner unexpectedly passes away or gets disabled, and their loved ones are left without the income to keep up with the mortgage -- they ultimately end up losing the home and all the equity they have saved up in it? Well what we do is help people qualify for financial protection plans so they don't have to worry about that.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">9. \"I need to talk to my spouse / partner.\"</div><div class=\"oa\">Okay, sure -- do you need to think about whether or not you want the coverage at all, or do you know you want the coverage and it's just a matter of which option you want to pick?<div class=\"opb\"><em>If they want it:</em> Completely understandable ___(client's name)___. You want to know what I'd recommend? Honestly, I'd recommend starting out at the low end for what you know you can afford, because you're actually going to see me twice. Once now, but also a year from now -- I simply check in, re-explain the policy benefits, and if you want to bump up the coverage at that time you certainly have the option. Anyway, the address we have on file to mail the policy out to is ____ right?<br/><br/><em>If they still don't want it:</em> Go back into the why and dig into their pain points on why they need the coverage.</div></div></div>\n<div class=\"obj-item\"><div class=\"oq\">10. \"I don't remember requesting this.\"</div><div class=\"oa\">Did maybe a spouse fill it out? Or a child? <em>(if no)</em> Do you currently have any protection for your family that pays out if you're sick, disabled, or pass away set up currently? Ok, well that's ok -- if you're anything like me I forgot what I had for breakfast. This will be quick, go ahead and grab a pen and paper and we can get this taken care of for you.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">11. \"I'm busy right now / Call me back later.\"</div><div class=\"oa\">I'm really busy as well and I have a lot of families to get to. I'll make this brief -- go ahead and grab something to write with so we can get this taken care of real quick.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">12. \"I'm driving.\"</div><div class=\"oa\">I don't want you to get in an accident -- go ahead and pull over real quick, I'll get your information pulled up.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">13. \"I'm at work.\"</div><div class=\"oa\">Perfect, I'll make this brief -- go ahead and grab something to write with so we can get this taken care of real quick.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">14. \"I've had a bad experience with insurance.\"</div><div class=\"oa\">Totally hear you -- some companies haven't always made it easy. What I can tell you is the carriers I work with are A-rated, with great reputations for paying claims. And I'm here to walk with you through the process step-by-step, no pressure. Out of curiosity -- was the issue with the policy itself, or how it was explained or handled?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">15. \"I already have insurance.\" / \"I already got this taken care of.\"</div><div class=\"oa\">Perfect, that's the reason for my call -- I see that on your file here. To confirm I'm speaking with the right person, it looks like the address we have on file for the policy is _______? Perfect, and looks like I have your Date of Birth listed on here as ___? Gotcha. Reason for my call is I'm the supervisor following up because it looks like one of our junior underwriters helped you with coverage but did not update your file here…<div class=\"opb\">Did you get the policy packet in the mail ok? Did you go with the complete plan or the partial plan? How much coverage? How much are you paying a month? Now which one of our companies did you end up going with? Is there a reason you went with one of our B-rated carriers? Could you not qualify for one of our top-rated ones? Any health issues at all?<br/><br/><em>*(look up quotes to see if you can get cheaper, OR build value on living benefits, cash value if it's a term, etc.)*</em><br/><br/>Ok, well this will only take a few minutes and we can get this switched for you. Looks like the mailing address we have on file for the policy is ______ ?</div></div></div>\n<div class=\"obj-item\"><div class=\"oq\">16. \"I'm confused -- I have homeowners insurance.\" (Allstate, Farmers, State Farm, AAA, etc.)</div><div class=\"oa\">Has anyone explained the difference between homeowners insurance and mortgage protection with you before?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">17. \"We took care of that at closing.\"</div><div class=\"oa\">Correct, you took care of your mortgage at closing -- but I'm calling in regards to the mortgage protection. The banks used to offer this back before 2008 but now it's contracted out directly to the various insurance carriers, which is who I work with. It's my job as the underwriter licensed with the state to run it through the various companies to figure out which option and product makes the most sense for you and your family. Make sense?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">18. \"We don't have that lender anymore.\"</div><div class=\"oa\">Correct, that's the reason for my call -- I see that on your file which is probably why it's still pending and slipped through the cracks on our end here, I apologize. To confirm I'm speaking with the right person, the address we have on file here for the mortgage is ___(address)___? Gotcha -- so as you may recall this is the coverage that takes care of the home God forbid you become sick, disabled, or pass away. Make sense?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">19. \"Are you with my bank?\"</div><div class=\"oa\">Yep, good question! ___(their lender)___ now handles the mortgage, refi, and equity side of things, and then after closing it's passed off to the mortgage protection department. It's always done right after closing and separately from the home, so that you're the beneficiary now and not the bank… does that make sense?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">20. \"Why wasn't this done before closing?\"</div><div class=\"oa\">Yep, good question. It USED to be done that way. ___(their lender)___ now handles the mortgage, refi, and equity side of things, and then after closing it's passed off to the mortgage protection department. It's always done right after closing and separately from the home, so that you're the beneficiary now and not the bank… does that make sense?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">21. \"I saw an ad.\" (accidental coverage confusion)</div><div class=\"oa\">Yes, that is for accidental coverage so it only covers you if you were to die in an accident. Were you looking for accidental only or did you want something that would cover you for any cause of death?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">22. \"I already have coverage through work.\"</div><div class=\"oa\">That's great that you have some through work -- but after you leave, retire, or change jobs all that coverage goes away. And worst case if you get cancer or some sort of illness and you end up getting laid off, you lose those benefits as well and then most likely you wouldn't be able to qualify health wise for any coverage. These are private policies and they're meant to be supplemented with private insurance. Anyway, it looks like the address we have on file for the home is ____?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">23. \"I already have PMI.\"</div><div class=\"oa\">PMI protects the bank -- not you or your family. If something happens to you, PMI does not pay off your mortgage or keep your family in the home. It simply means the bank recovers their money. Mortgage protection is the coverage that actually works for your family. Those are two very different things.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">24. \"I just want to think about it.\"</div><div class=\"oa\">Totally respect that. Is there something still unclear, or are you just needing a little time? What we can do is submit the application just to see what you qualify for -- no commitment, and you can still think it over while it's reviewed. That way you lock in your health rating now in case anything changes later.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">25. \"Can you just send me something?\"</div><div class=\"oa\">Of course -- these plans are tailored based on your age, health, and mortgage balance. So if I just send something it's going to be generic and not even accurate. Would you prefer options with lower monthly payments or ones that pay the mortgage off in full? Let me get you real numbers based on your actual situation.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">26. \"I want to compare other options.\"</div><div class=\"oa\">That's smart -- and I'll save you the time. I'm a broker. I represent multiple top-rated carriers. I already ran you through the field and these are the best options available in your state for your health profile and mortgage situation. You're already looking at a comparison. What specifically are you hoping to find somewhere else?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">27. \"Do you have anything cheaper?\"</div><div class=\"oa\">When you jump out of a plane do you want the cheapest parachute or the best parachute? If you just want cheap life insurance I can certainly help you with that -- but you mentioned the ___(cash value AND/OR living benefits)___ was important to you?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">28. \"Let me sleep on it.\"</div><div class=\"oa\">Totally fair. What I recommend is that we submit the application to lock in your age and health now, and while it's in review you've got time to decide. If you change your mind, no problem -- no payment required.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">29. \"Do I have to make a decision today?\"</div><div class=\"oa\">Yes, I do need to submit that original coverage through today -- however, since most of us need time to look over our finances to see which option we want to go with, which is understandable, what I'd recommend for your situation is simply starting out on the low end for what you know you can afford. If you want to bump up the coverage you can always give me a call or shoot me a text. I also do annual reviews with my clients so we will review this a year from now and you'll have the option to bump it up at that point as well. Anyway, the address we have on file to mail the policy out to is ____ right?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">30. \"We don't need mortgage protection -- our home is covered with our life insurance.\"</div><div class=\"oa\">Gotcha -- has anyone explained the difference between mortgage protection and life insurance to you before? So mortgage protection and life insurance both pay out as a check directly to your beneficiary when you pass away. The reason that mortgage protection is a bit better is because mortgage protection covers you on the living side as well -- NOT JUST the death side. What that means is any situation where you get sick, disabled, cancer, heart attack, stroke, or any other sort of critical, chronic, or terminal illness this policy is paying out as well in order to supplement that loss of income and pay for any medical bills. I'm not sure if you're aware of this ___(client's name)___ but the biggest cause of bankruptcies and home foreclosures is NOT due to a death -- it's either due to unforeseen medical bills, or being disabled for a period of time and not being able to work. That is why our clients love this coverage so much, because you have an 89% higher likelihood of becoming disabled or sick than you are of passing away. Does that make sense?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">31. \"What if I pay into it and never use it?\"</div><div class=\"oa\">That's exactly why this is designed to protect your family during the years they'd be most impacted -- while the mortgage is active. It's peace of mind knowing the home's protected while it's still a big liability.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">32. \"I'll be okay -- my family can figure things out.\"</div><div class=\"oa\">I respect that -- but can I be real with you for a second? Most families don't figure it out. Grieving plus mortgage payments is a heavy combination. Mortgage protection is about giving your loved ones the gift of time -- time to grieve, to adjust, and to stay in the home without scrambling.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">33. \"I'm still young -- I've got time.\"</div><div class=\"oa\">That's exactly why now is the smartest time. You qualify for the best rates and the most coverage while you're young and healthy. Waiting doesn't make it cheaper -- it only makes it riskier. This kind of coverage is like locking in your health today -- even if things change tomorrow.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">34. \"I don't want to commit to anything long-term.\"</div><div class=\"oa\">Good news is many of these plans aren't lifelong commitments -- you can structure them to match your mortgage term or even shorter. We can also start with something small, get you protected now, and adjust later as life changes. You stay in control the whole time.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">35. \"Why do you need my Social Security number?\" / \"I'm not comfortable giving that out.\"</div><div class=\"oa\">Understood, I hear ya (client's name). The insurance carrier requires that because that's how they're going to check your medical and prescription history, and it also prevents fraud so someone's not signing up for coverage in your name. Does that make sense? Okay cool -- confirm that social with me again?<div class=\"opb\"><em>If they give more pushback:</em> We actually have insurance that if anybody were able to get through all of our firewalls and access your info, it would cover you for up to a million dollars. That should be enough, right? <em>(wait for response)</em> Ok, go ahead with the social.</div></div></div>\n<div class=\"obj-item\"><div class=\"oq\">36. \"Why do you need my bank information?\" / \"I don't want to give that out.\"</div><div class=\"oa\">The insurance carrier either requires a voided check or account number to verify there is no insurance fraud, money laundering, or anything else fraudulent linked to your account -- and of course that's also how you'll be paying for the policy once you're approved. Anyway, looks like the address we have on file to mail the policy out to is ___?<div class=\"opb\"><em>If they're still giving pushback:</em> I also just texted you a link to the Department of Insurance to look up my information and make sure I'm legit. Let me know when you get the link. <em>(walk them through how to verify your license: https://sbs.naic.org/solar-external-lookup)</em></div></div></div>" },
  { id: "iul_all", html: "<div class=\"obj-item\"><div class=\"oq\">\"I've never heard of an IUL -- is this legit?\"</div><div class=\"oa\">100% -- Indexed Universal Life is one of the most powerful financial products in existence and has been around for decades. Walt Disney used it to fund Disneyland when the banks wouldn't give him a loan. It's a whole life insurance policy with a cash value component tied to a stock market index.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I already have a 401K -- why do I need this?\"</div><div class=\"oa\">Great question -- and the answer is taxes and control. Your 401K is tax-deferred, meaning you pay taxes when you take the money out at whatever rate applies then. An IUL grows tax-free and the money comes out tax-free. And unlike your 401K, you're not penalized for accessing it before 59 and a half. They're complementary strategies -- not competing ones.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"Is this a whole life policy? I heard those are bad.\"</div><div class=\"oa\">You've probably heard that from people comparing whole life to term for pure death benefit -- and in that context, they're right. But an IUL is a different animal. It's designed specifically for people who want the life insurance benefit and the cash value growth. If you just want the cheapest death benefit, buy term. If you want a financial vehicle that builds wealth, protects your family, and gives you tax-free access -- that's what this is.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"What if I need the money before I expected to?\"</div><div class=\"oa\">That's actually one of the features, not a bug. The cash value in an IUL is accessible at any time through a policy loan. No penalty, no tax, no questions from the IRS. You borrow against the death benefit, the cash value keeps growing as if you never touched it, and you pay it back on your own timeline.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I'm not sure I need life insurance.\"</div><div class=\"oa\">Let me ask you this -- if you passed away tomorrow, is there anyone whose life would be financially impacted? A spouse, kids, parents, a business partner? If the answer is yes, then the question is not whether you need it -- it's how much, what kind, and how to make it work the hardest for you.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I can't afford another monthly payment.\"</div><div class=\"oa\">That's actually the conversation I want to have -- because I don't know yet what makes sense for your situation. Some clients put in $100 a month. Some put in $1,000. What I want to figure out is what amount, if you set it aside every month into something that builds compound interest and never goes down in a down market, would actually feel worth it to you.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"My employer already has life insurance on me.\"</div><div class=\"oa\">How much? And what happens to it if you change jobs or get laid off? Employer-provided life insurance is group coverage -- it's not yours, not permanent, and not portable. Most of those policies are term and they disappear the moment your employment ends. What I'm talking about is something you own, forever, regardless of where you work.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I want to do my own research first.\"</div><div class=\"oa\">Please do -- I actually encourage it. Look up Indexed Universal Life and how the S&amp;P 500 floor works. Look up the carriers I mentioned. Verify my license. Then call me back and we can have an even better conversation. While you're researching, pay attention to the tax-free loan provision -- because that's the piece most financial articles miss.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"What if the stock market crashes?\"</div><div class=\"oa\">That's the best part -- and it's what makes an IUL different from everything else. Your index has a floor of zero. If the market goes down 30%, your cash value goes down zero. You simply don't participate in the loss. When the market recovers, you start earning again from wherever you left off.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"How is this different from just investing in the S&amp;P 500 directly?\"</div><div class=\"oa\">Three things. First -- the floor. In the S&amp;P 500 directly, a down year means you lose money. In an IUL, a down year means you stay flat. Second -- taxes. Your S&amp;P gains are taxed. Your IUL cash value grows tax-free and comes out tax-free. Third -- the death benefit. Your S&amp;P account does not pay your family a lump sum if you die. Your IUL does.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"What are the fees?\"</div><div class=\"oa\">There are internal costs of insurance -- the actual cost of the death benefit -- which is taken out of the premium. These are disclosed fully in the illustration I'll send you. Even accounting for those costs, the tax advantage and floor protection make the net return competitive over a long timeline.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"What is the cap on growth?\"</div><div class=\"oa\">Most IUL policies have a participation rate and a cap -- typically between 10% and 14% depending on the carrier. The trade-off for the cap is the floor -- you never lose. Over a long timeline, that combination outperforms most taxable accounts because you're never starting from a loss.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"The quote seems high.\"</div><div class=\"oa\">Let me reframe that. You're not spending money -- you're moving money into an asset that builds compound interest, protects your family, and gives you tax-free access. What would you normally do with that money each month? Leave it in a checking account earning near-zero interest? This is the same money doing a completely different job.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I want to think about it before I pick an amount.\"</div><div class=\"oa\">Totally fair -- and here's a thought. We can start you at the minimum just to see what you qualify for and lock in your health rating today. You can always adjust the amount once you see the full illustration. There's no right or wrong answer -- it's just about getting you into the right structure. What would feel like a comfortable starting point?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"How does the loan actually work -- won't I owe interest?\"</div><div class=\"oa\">Great question. When you take a policy loan, you're borrowing against your death benefit -- not from the cash value itself. The cash value stays in the index earning compound interest the whole time. The loan does accrue a small interest charge, but in most cases the growth in the index more than offsets it. And there are no required repayment terms -- you pay it back on your own schedule or it reduces the death benefit.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I want to talk to my financial advisor first.\"</div><div class=\"oa\">Absolutely -- and I respect that. One thing to flag when you have that conversation: most financial advisors are either fee-based or securities-licensed. They're incentivized to direct you toward products they manage. Ask them specifically about the tax-free loan provision of an IUL and watch the reaction. If they're familiar with it, great. If they dismiss it without explaining it -- that tells you something.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"What if the carrier goes out of business?\"</div><div class=\"oa\">Life insurance companies are regulated at the state level and most states have guarantee associations that protect policyholders even if the carrier fails. We also only work with A-rated carriers -- companies that have been around 50 to 100 years and have the reserves to back every policy they've ever written.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I'm too young to worry about this.\"</div><div class=\"oa\">You're actually exactly the right age -- and that's not a sales line, it's math. The younger and healthier you are when you lock in a permanent policy, the lower your cost of insurance inside the policy, and the more of your premium goes into cash value. Every year you wait costs you in three ways: higher rates, less time to compound, and the risk that your health changes.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I'll just invest the money myself.\"</div><div class=\"oa\">I love that instinct -- and if you'll actually do it consistently, every month without exception, never touch it, and not mind paying taxes on the gains, then yes, direct investing can work. But here's the honest question: what percentage of people actually do that with discipline over 20 or 30 years? And what happens to your plan if you get sick, disabled, or die before the account is large enough to replace your income? This is the piece self-directed investing can't answer.</div></div>" },
  { id: "fia_all", html: "<div class=\"obj-section-label\">CALL 1 -- OPENER</div>\n<div class=\"obj-item\"><div class=\"oq\">\"I've never heard of a Fixed Indexed Annuity.\"</div><div class=\"oa\">That's completely normal -- FIAs are underutilized and underexplained. Let me give you the one-sentence version: your money grows when the market goes up, up to a cap, and earns zero when the market goes down. Your principal is guaranteed. That's the core promise.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I don't want to talk about my finances.\"</div><div class=\"oa\">I completely respect that -- and I'm not here to pry. All I need is a rough sense of the ballpark so I can tell you honestly whether what I do is even relevant for your situation. If it's not a fit, I'll tell you. Fair?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I already have a financial advisor.\"</div><div class=\"oa\">That's great -- and I'm not here to replace anyone. What I specialize in specifically is the protection side of retirement money -- making sure a portion of your savings literally cannot go down. A lot of advisors don't offer FIAs because they're not securities products. It's worth knowing your options.</div></div>\n<div class=\"obj-section-label\">CALL 1 -- FUNDS DISCOVERY</div>\n<div class=\"obj-item\"><div class=\"oq\">\"I don't want to tell you how much I have.\"</div><div class=\"oa\">Totally fair -- even a range helps me. Just a rough ballpark so I can make sure the product I show you on our second call actually makes sense for your situation. Would you say it's under $100k, somewhere in between, or over $250k?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"It's in my 401k and I can't touch it.\"</div><div class=\"oa\">If it's with a current employer and you're still actively contributing -- you're right, we can't move it. But if it's from a previous employer, a rollover is completely available to you with zero tax consequences if done correctly. Which situation are you in?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"My money is doing fine where it is.\"</div><div class=\"oa\">That's great to hear -- and I'm not here to tell you to move everything. The question I always ask is: what happens to 'doing fine' if the market drops 30% next year? For money you're planning to retire on, 'fine' isn't the same as 'protected.' That's the conversation worth having.</div></div>\n<div class=\"obj-section-label\">CALL 1 -- PAIN DISCOVERY</div>\n<div class=\"obj-item\"><div class=\"oq\">\"The market has been great -- why would I change anything?\"</div><div class=\"oa\">The best time to put a seatbelt on is before the crash, not during. For retirement money specifically, a 30% loss the year before you retire isn't something you get to wait out. It changes your life. That's the risk we're talking about eliminating.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I'm not worried about losing money.\"</div><div class=\"oa\">I respect that confidence. Can I ask -- have you experienced a significant market drop with this money before? Most people who've lived through 2008 or 2020 with real retirement money say the same thing beforehand. The goal isn't to scare you -- it's to make sure the money you've spent decades building is never at risk of a catastrophic setback.</div></div>\n<div class=\"obj-section-label\">CALL 1 -- PRODUCT CONCEPT</div>\n<div class=\"obj-item\"><div class=\"oq\">\"What's the catch?\"</div><div class=\"oa\">The catch is the cap. Because the insurance company is guaranteeing you can never lose money, they put a ceiling on how much you can gain in any given year. You give up some upside in exchange for absolute downside protection. For most people protecting retirement savings, that's not a hard trade to make.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"So my money isn't actually in the market?\"</div><div class=\"oa\">Correct -- and this trips a lot of people up. Your money is held by the insurance company in their general account. The index is just the measuring stick for how your growth gets calculated. You get the upside of index performance up to the cap, and a guaranteed floor of zero on the downside. You're participating in the market's gains without being exposed to its losses.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I don't fully understand how this works.\"</div><div class=\"oa\">One sentence: your money grows when the market goes up, up to a cap, and earns zero when the market goes down. Your principal never decreases. That's it. Everything else is just mechanics underneath that one core promise. What specific part feels confusing? Let me clear it up.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"What's a cap rate -- and what if the cap changes?\"</div><div class=\"oa\">The cap rate is the maximum you can earn in a given crediting period. Cap rates can change at renewal based on interest rates and bond yields. But even at a lower cap, the floor guarantee still holds. Your worst year is always zero. That doesn't change.</div></div>\n<div class=\"obj-section-label\">CALL 2 -- EDUCATION AND COMPARISON</div>\n<div class=\"obj-item\"><div class=\"oq\">\"The market has been doing great -- why would I cap my upside?\"</div><div class=\"oa\">If the market keeps going up forever with no corrections, yes -- you'd do better fully invested. But 2008 was down 38%. 2022 was down 19%. COVID dropped 34% in a month. When those years hit -- and they will again -- the person in an FIA earned zero. The person fully in the market potentially needed years to recover. For retirement money you can't afford to rebuild, the cap is cheap insurance.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I can get a better return in stocks.\"</div><div class=\"oa\">You might. But can you guarantee you won't experience a 30% drop the year before you need to retire? The FIA isn't competing with your aggressive growth accounts -- it's competing with the risk of catastrophic loss on money you can't replace. Think of it as the foundation of your retirement -- the part that never breaks no matter what.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"A CD or money market is simpler.\"</div><div class=\"oa\">Simpler, yes. But a CD resets at term end and you pay taxes on the interest every single year. An FIA has the potential to earn double digits in strong market years, growth is tax-deferred, and the floor protects you from loss. Over a 7-10 year period, the tax deferral and upside participation historically leave you ahead of a CD -- without any principal risk.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"My financial advisor said annuities are bad.\"</div><div class=\"oa\">Most legitimate criticism of annuities is aimed at variable annuities -- products that ARE in the market, charge 2-3% in annual fees, and can lose value. A Fixed Indexed Annuity is fundamentally different: no market exposure, no internal investment fees, and a 0% floor guarantee. Ask your advisor specifically what their objection is to a product that cannot lose principal. That's a different conversation.</div></div>\n<div class=\"obj-section-label\">CALL 2 -- TRUST AND COMPANY</div>\n<div class=\"obj-item\"><div class=\"oq\">\"I've never heard of that company.\"</div><div class=\"oa\">What matters is their financial strength rating -- they're A-rated by AM Best, the independent gold standard for insurance company stability. Annuities are also protected under the state guaranty association up to $250,000 per contract holder.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"What happens if the insurance company goes under?\"</div><div class=\"oa\">Insurance companies are regulated at the state level and required to hold reserves to cover their policy obligations. In the extremely rare case of insolvency, the state guaranty association covers annuity contracts -- similar to how the FDIC covers bank deposits. Protection is typically up to $250,000 per contract.</div></div>\n<div class=\"obj-section-label\">CALL 2 -- LIQUIDITY AND ACCESS</div>\n<div class=\"obj-item\"><div class=\"oq\">\"What if I need the money?\"</div><div class=\"oa\">Built right into the contract is a free withdrawal provision -- you can access up to 10% of your account value every year without any surrender charge. Most carriers also waive surrender charges entirely for hospitalization, nursing home confinement, or terminal illness. So you're not locked out of your money -- you just have a structure around the bulk of it.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I don't want to be locked in for 7 or 10 years.\"</div><div class=\"oa\">Think about what 'locked in' actually means here: your money is growing, protected, and you have 10% annual access. The surrender period exists because the insurance company needs time to generate the returns that fund your cap and floor guarantees. The question is: do you realistically need more than 10% of this money in any given year? If the answer is no, the surrender period isn't really a constraint.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"What are the fees on this?\"</div><div class=\"oa\">The base FIA has no explicit annual fee -- no management fee or expense ratio the way you'd see in a mutual fund or variable annuity. The cost is built into the cap rate.<div class=\"opb\"><em>If income rider:</em> The income rider carries a fee -- typically around [Rider Fee]% annually. For most clients, the income that rider generates far exceeds that cost over the life of the contract.</div></div></div>\n<div class=\"obj-section-label\">CALL 2 -- SPOUSE AND FAMILY</div>\n<div class=\"obj-item\"><div class=\"oq\">\"I need to talk to my spouse first.\"</div><div class=\"oa\">Of course -- and I'd want them involved. In fact, let's get them on the next call. This affects both of you and I want both of you confident in the decision. When's a time that works for both of you? I'll do a quick walkthrough, answer every question, and you can decide together.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"My spouse thinks annuities are a scam.\"</div><div class=\"oa\">That's more common than you'd think -- and it comes from real experiences with bad annuity products. Variable annuities with hidden fees absolutely deserve that reputation. A Fixed Indexed Annuity with a 0% floor, no internal investment fees, and a state-backed guarantee is a completely different animal. Get your spouse on a call with me -- I'd rather clear it up directly than have a misunderstanding drive the decision.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"My kids think I should just keep it in the market.\"</div><div class=\"oa\">Your kids want you to grow your money -- that's great. But they're not retiring on this money. You are. Ask them this: what's the plan if the market drops 30% the year before you retire? A Fixed Indexed Annuity means that question is never on the table.</div></div>\n<div class=\"obj-section-label\">CALL 2 -- TIMING AND STALLS</div>\n<div class=\"obj-item\"><div class=\"oq\">\"I need to think about it.\"</div><div class=\"oa\">Totally fair -- this is a big decision. Can I ask what specifically you want to think through? Because if there's a question I haven't answered, I want to make sure you have everything before we hang up. What would need to be true for you to feel ready to move forward?</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I want to wait and see what the market does.\"</div><div class=\"oa\">The whole point of this product is that it doesn't matter what the market does. If it goes up, you earn up to [Cap Rate]. If it goes down, you earn zero. Waiting to see what the market does before you protect yourself from the market is like waiting to see if it rains before you buy an umbrella. The protection starts the day the contract is in force.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"I'm not ready to make a decision today.\"</div><div class=\"oa\">No pressure. I never want you to feel rushed. Is there something specific still on your mind, or is it more of a gut feeling? My job isn't to push you into something -- it's to make sure you have everything you need to make the right call. What would change between now and whenever you feel ready?</div></div>\n<div class=\"obj-section-label\">CALL 2 -- ROLLOVER AND TAX</div>\n<div class=\"obj-item\"><div class=\"oq\">\"Won't I owe taxes when I move the money?\"</div><div class=\"oa\">Not if we do it the right way -- and that's our job to make sure it's done right. A direct rollover from your [Source of Funds] into an IRA-held annuity is a non-taxable transfer. The IRS doesn't treat it as a distribution. No taxes, no penalties, no withholding. It goes from one institution to another without you ever touching it.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"What if my 401k has a match I'd lose?\"</div><div class=\"oa\">If you're still employed and still receiving the employer match, we'd never recommend moving that money -- you don't want to leave free money on the table. But if this is from a previous employer, or you're no longer actively contributing and receiving a match, there's nothing to lose by rolling it to a vehicle that's working harder for you.</div></div>\n<div class=\"obj-item\"><div class=\"oq\">\"This sounds complicated.\"</div><div class=\"oa\">I hear you -- but here's what matters: your money grows when the market goes up, up to a cap. It stays flat when the market goes down. You can never lose principal. And when the term is up, you have full flexibility. Everything else is just contract language. My job is to make sure you understand the core promise and handle everything else. What specific part feels confusing? Let me clear it up.</div></div>" },
];
